return items.map(item => {
  const data = item.json;

  let aiResult = {};

  try {
    if (typeof data.output === "string") {
      aiResult = JSON.parse(data.output);
    } else if (
      data.output &&
      typeof data.output === "object"
    ) {
      aiResult = data.output;
    }
  } catch (error) {
    aiResult = {
      analysis_status: "AI parsing failed",
      kpi_issue: "",
      performance_summary: data.output || "",
      possible_reason: "",
      business_impact: "",
      recommended_action: "",
      priority: data.Severity || ""
    };
  }

  return {
    json: {
      KPI_ID: data.KPI_ID,
      Date: data.Date,
      KPI_Name: data.KPI_Name,
      Category: data.Category,
      Department: data.Department,
      Actual_Value: data.Actual_Value,
      Target_Value: data.Target_Value,
      Unit: data.Unit,
      Variance: data.Variance,
      Variance_Percentage: data.Variance_Percentage,
      Achievement_Percentage: data.Achievement_Percentage,
      KPI_Status: data.KPI_Status,
      Severity: data.Severity,

      AI_Analysis_Status:
        aiResult.analysis_status || "",

      KPI_Issue:
        aiResult.kpi_issue || "",

      Performance_Summary:
        aiResult.performance_summary || "",

      Possible_Reason:
        aiResult.possible_reason || "",

      Business_Impact:
        aiResult.business_impact || "",

      Recommended_Action:
        aiResult.recommended_action || "",

      AI_Priority:
        aiResult.priority || ""
    }
  };
});

return items.map(item => {
  const data = item.json;

  const requiredFields = [
    "KPI_ID",
    "Date",
    "KPI_Name",
    "Category",
    "Department",
    "Actual_Value",
    "Target_Value",
    "Unit"
  ];

  const missingFields = requiredFields.filter(
    field =>
      data[field] === undefined ||
      data[field] === null ||
      data[field] === ""
  );

  const actual = Number(data.Actual_Value);
  const target = Number(data.Target_Value);

  const errors = [];
  let validationStatus = "Valid";

  if (missingFields.length > 0) {
    validationStatus = "Invalid";
    errors.push(
      `Missing fields: ${missingFields.join(", ")}`
    );
  }

  if (isNaN(actual)) {
    validationStatus = "Invalid";
    errors.push("Actual_Value must be numeric");
  }

  if (isNaN(target)) {
    validationStatus = "Invalid";
    errors.push("Target_Value must be numeric");
  }

  if (target === 0) {
    validationStatus = "Invalid";
    errors.push("Target_Value cannot be zero");
  }

  return {
    json: {
      ...data,
      Validation_Status: validationStatus,
      Validation_Errors: errors.join("; ")
    }
  };
});

return items.map(item => {
  const data = item.json;

  const actual = Number(data.Actual_Value);
  const target = Number(data.Target_Value);

  const variance = actual - target;

  const variancePercentage =
    target !== 0
      ? (variance / target) * 100
      : 0;

  const achievementPercentage =
    target !== 0
      ? (actual / target) * 100
      : 0;

  return {
    json: {
      ...data,

      Actual_Value: Number(actual.toFixed(2)),
      Target_Value: Number(target.toFixed(2)),
      Variance: Number(variance.toFixed(2)),
      Variance_Percentage: Number(
        variancePercentage.toFixed(2)
      ),
      Achievement_Percentage: Number(
        achievementPercentage.toFixed(2)
      )
    }
  };
});

return items.map(item => {
  const data = item.json;

  const variancePercentage =
    Number(data.Variance_Percentage || 0);

  let status;
  let severity;

  if (variancePercentage >= 0) {
    status = "On Track";
    severity = "Low";
  } else if (variancePercentage >= -10) {
    status = "Warning";
    severity = "Medium";
  } else if (variancePercentage >= -20) {
    status = "At Risk";
    severity = "High";
  } else {
    status = "Critical";
    severity = "Critical";
  }

  return {
    json: {
      ...data,
      KPI_Status: status,
      Severity: severity
    }
  };
});
